contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public {
        // Ensure the caller (this contract) is not the owner.
        // Since this contract deployed c, it is the owner, so we must change ownership
        // by having the owner withdraw all balance to itself, making the owner address this contract,
        // but wait: the owner is msg.sender at c's construction, which is this contract.
        // So this test contract IS the owner. To test a non-owner caller, we need a different caller.
        // However the checker always calls from this contract. So we cannot be non-owner.
        // Therefore we need a different rule that does not require a non-owner caller.

        // Alternative: test that owner withdraw(v) reverts if v > balance, and does not change state.
        // But the accepted rules already cover withdraw. Let's instead test that sendMoney with
        // a reverting call does not change balance.
        // But we need a general rule about non-owner? Impossible because we are owner.
        // So let's pivot: use a rule about receive() increasing depositsCount and balance
        // which is already covered by accepted rules? No, the accepted rule says direct value
        // transfer increases depositsCount by one and balance by amount. That's already accepted.

        // Let's test that a successful withdraw decreases balance and increases caller balance.
        // Already accepted.

        // Need a different rule. Maybe: a call to withdraw with value 0 does not revert and
        // does not change balances? But that's trivial? The assert must be general.
        // Actually: for any owner call to withdraw(v) where v <= address(c).balance,
        // the call succeeds, c's balance decreases by v, and depositsCount unchanged.
        // But that's similar to accepted rule.

        // Let's look at the contract: withdraw uses .transfer which reverts if insufficient balance.
        // So if v > balance, it reverts and state unchanged. That is a general rule.
        // So: if v > address(c).balance, withdraw(v) reverts, c balance unchanged, depositsCount unchanged.

        // But we need to ensure c has some balance. Since we are owner, we can first withdraw all
        // to ourselves to get some balance? No, we need to set up balance >0. We can do a sendMoney to c?
        // Actually we can deposit via receive by sending ether directly: address(c).call{value: amount}("");
        // But that would change depositsCount. Then we can test withdraw with v > balance.

        // However the test must be a single transaction. We can do:
        // 1. Deposit some ether into c by calling c with value (receive).
        // 2. Then call withdraw with v > balance, expect revert.

        // Let's do that. We need to send ether to c. Since this contract is owner, we can
        // call c with value. But we need to take amount as a parameter.

        // Actually the rule: for any v > address(c).balance, withdraw(v) reverts, c's balance
        // and depositsCount unchanged.
        // But we need to ensure that before the call, c's balance is known. We can read it,
        // then call withdraw(v) with v > that balance. But to avoid triviality, we need to
        // ensure that the precondition v > address(c).balance is satisfied for the given v.
        // Since address(c).balance can be anything, we can just require(v > address(c).balance)
        // at the start. But that is a precondition on the parameter and the state.

        // However, is it possible that address(c).balance is so large that v (uint256) cannot
        // be greater? v is uint256, balance is uint256, so v could be max. It's possible.

        // But the contract's withdraw uses .transfer which forwards 2300 gas. If the caller
        // is a contract without a receive/fallback that can accept, the transfer might revert
        // even if balance is sufficient? This contract is InvMutTest, and it has a receive
        // that does nothing, so it can receive ether. So transfer will succeed if enough balance.

        // So the rule holds: if v > balance, transfer fails, withdraw reverts.

        // Let's write that.

        uint cBalanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        require(v > cBalanceBefore, "v must exceed balance");

        bool reverted = false;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && address(c).balance == cBalanceBefore && c.depositsCount() == depositsBefore);
    }

    receive() external payable {}
}

